import type { Dir } from './iso';

/** Directions generated by PixelLab; the other three are mirrored (P-54). */
const MIRROR: Partial<Record<Dir, Dir>> = { sw: 'se', w: 'e', nw: 'ne' };

export function spriteDir(dir: Dir): { dir: Dir; flip: boolean } {
	const m = MIRROR[dir];
	return m ? { dir: m, flip: true } : { dir, flip: false };
}

export type HeroAnim = 'idle' | 'walk8' | 'attack' | 'hurt' | 'death' | 'super';

/** Higher wins while it is playing (a hit does not cancel death, walking does not cancel an attack). */
const PRIORITY: Record<HeroAnim, number> = {
	idle: 0,
	walk8: 0,
	attack: 1,
	hurt: 2,
	super: 3,
	death: 4,
};

export function canInterrupt(
	current: HeroAnim | null,
	currentPlaying: boolean,
	next: HeroAnim,
): boolean {
	if (!current || !currentPlaying) return true;
	return PRIORITY[next] >= PRIORITY[current];
}

/** Base loop when nothing else plays. */
export function locomotion(moving: boolean): HeroAnim {
	return moving ? 'walk8' : 'idle';
}

/** Frames per second so a one-shot animation fits in `seconds` (never slower than `min`). */
export function fpsToFit(frames: number, seconds: number, min: number): number {
	return Math.max(min, Math.ceil(frames / Math.max(0.05, seconds)));
}
